The new policy reasons about how much damage a cannon can actually deliver before the leading pirate in its column reaches the loss position. It computes the *deficit* – the extra damage points that must be added (by spawning/merging) so the cannon can kill the front pirate in time. The action chooser first fixes any column that still has a deficit (by spawning into that column, which merges and raises its damage). If no deficits exist it places new cannons in empty but threatened columns, and only when every column is already safe does it move the weakest cannon onto the most dangerous column to give it an extra damage point. This deterministic, damage‑budget approach removes many unnecessary spawns and ensures merges are performed exactly when required, raising the win‑rate.

```python
NUM_COLUMNS = 5
MAX_POSITION = 2          # position 3 ends the game
LOSS_POSITION = 3

class Policy:
    name = "damage_budget_v1"

    def choose_action(self, engine):
        # 1. Compute deficit for each column (extra damage needed)
        deficits = {}
        for col in range(NUM_COLUMNS):
            deficit = self._column_deficit(engine, col)
            deficits[col] = deficit

        # 2. If any column still needs extra damage, spawn there to merge
        cols_needing = [c for c, d in deficits.items() if d > 0]
        if cols_needing:
            # pick the column with the largest deficit (most urgent)
            target = max(cols_needing, key=lambda c: deficits[c])
            return ("spawn", target)

        # 3. No deficits – try to place a new cannon in an empty but threatened column
        threatened_empty = [
            c for c in range(NUM_COLUMNS)
            if c not in engine.cannons and self._has_threat(engine, c)
        ]
        if threatened_empty:
            # choose the column where the leading pirate is furthest forward
            target = max(threatened_empty,
                         key=lambda c: self._front_position(engine, c))
            return ("spawn", target)

        # 4. All columns have cannons and are safe; if there is any empty column, fill it
        empty_cols = [c for c in range(NUM_COLUMNS) if c not in engine.cannons]
        if empty_cols:
            return ("spawn", empty_cols[0])

        # 5. All columns occupied and safe – improve the weakest cannon by moving it
        #    onto the column with the highest total pirate HP (most future pressure).
        weakest_col = min(engine.cannons.items(),
                          key=lambda kv: kv[1].damage)[0]

        # find a target column (different from source) with the highest cumulative HP
        target_col = max(
            (c for c in range(NUM_COLUMNS) if c != weakest_col),
            key=lambda c: self._total_hp(engine, c)
        )
        # If moving would not increase damage (target already has high damage),
        # just spawn in the weakest column (no move needed).
        if target_col == weakest_col:
            return ("spawn", weakest_col)

        return ("move", weakest_col, target_col)

    # --------------------------------------------------------------------- #
    # Helper calculations
    # --------------------------------------------------------------------- #
    @staticmethod
    def _front_pirate(engine, column):
        """Return the pirate with the highest position in the given column, or None."""
        pirates = [p for p in engine.pirates if p.column == column]
        if not pirates:
            return None
        return max(pirates, key=lambda p: p.position)

    @staticmethod
    def _front_position(engine, column):
        fp = Policy._front_pirate(engine, column)
        return fp.position if fp else -1

    @staticmethod
    def _has_threat(engine, column):
        """True if there is any pirate in the column."""
        return any(p.column == column for p in engine.pirates)

    @staticmethod
    def _total_hp(engine, column):
        """Sum of HP of all pirates in the column (used as a proxy for future pressure)."""
        return sum(p.hp for p in engine.pirates if p.column == column)

    @staticmethod
    def _column_deficit(engine, column):
        """
        How many extra damage points are required for the cannon in this column
        to kill the leading pirate before it reaches position 3.
        Returns 0 if no cannon is needed or the column is already safe.
        """
        front = Policy._front_pirate(engine, column)
        if front is None:
            # No pirate – no deficit
            return 0

        rounds_left = LOSS_POSITION - front.position
        if rounds_left <= 0:
            # Already at loss; treat as infinite deficit (force immediate action)
            return 999

        # Damage needed per round to kill the pirate in time
        needed_damage = (front.hp + rounds_left - 1) // rounds_left  # ceil division

        if column in engine.cannons:
            current_damage = engine.cannons[column].damage
        else:
            # If we spawn a new cannon here, it will start with damage 1 immediately
            current_damage = 1

        deficit = needed_damage - current_damage
        return max(0, deficit)
```

