```python
NUM_COLUMNS = 5
MAX_POSITION = 3   # reaching this loses the game


class Policy:
    name = "deficit_based_merge_v1"

    def choose_action(self, engine):
        front = self._front_pirates(engine)          # most‑advanced pirate per column
        col_pirates = self._pirates_by_column(engine)  # list of pirates per column

        # ---------- compute deficit for each column ----------
        deficits = {}   # column -> deficit (positive means not enough damage)
        for col in range(NUM_COLUMNS):
            pirates = col_pirates[col]
            if not pirates:
                continue            # no threat in this column

            # total HP that must be dealt in this column
            total_hp = sum(p.hp for p in pirates)

            # how many shots we will get before any pirate reaches position 3
            shots = max(MAX_POSITION - p.position for p in pirates)
            shots = max(shots, 0)

            cannon = engine.cannons.get(col)
            dmg_per_shot = cannon.damage if cannon else 0

            potential = dmg_per_shot * shots
            deficit = total_hp - potential
            if deficit > 0:
                deficits[col] = deficit

        # ---------- helper: weakest donor cannon ----------
        def weakest_donor(exclude=None):
            candidates = [(ccol, c.damage) for ccol, c in engine.cannons.items()
                          if ccol != exclude]
            if not candidates:
                return None
            # deterministic: lowest damage, then lowest column
            return min(candidates, key=lambda kv: (kv[1], kv[0]))[0]

        # ---------- 1. Resolve biggest deficit by moving a weak cannon ----------
        if deficits:
            # column with the largest deficit (tie‑break by lower column)
            target = max(deficits.items(), key=lambda kv: (kv[1], -kv[0]))[0]
            donor = weakest_donor(exclude=target)
            if donor is not None:
                return ("move", donor, target)

        # ---------- 2. If deficit exists but no donor, spawn (will merge) ----------
        if deficits:
            # pick the column with the largest deficit again
            target = max(deficits.items(), key=lambda kv: (kv[1], -kv[0]))[0]
            return ("spawn", target)

        # ---------- 3. No deficits – fill empty columns or strengthen weak spots ----------
        empty_cols = [c for c in range(NUM_COLUMNS) if c not in engine.cannons]
        if empty_cols:
            # Prefer an empty column that already has a pirate (so the cannon is useful immediately)
            for c in empty_cols:
                if front.get(c) is not None:
                    return ("spawn", c)
            # otherwise just take the first empty column
            return ("spawn", empty_cols[0])

        # ---------- 4. All columns occupied and no urgent need – improve weakest cannon ----------
        # merge the weakest cannon into the column with the most advanced pirate
        weakest = min(engine.cannons.items(), key=lambda kv: (kv[1].damage, kv[0]))[0]
        # target = column with highest front pirate position (if any)
        target = max(
            (c for c in engine.cannons if front.get(c) is not None),
            key=lambda c: front[c].position,
            default=weakest,
        )
        if weakest != target:
            return ("move", weakest, target)

        # fallback (should never happen): spawn on weakest column
        return ("spawn", weakest)

    # --------------------------------------------------------------------- #
    @staticmethod
    def _front_pirates(engine):
        """Return dict column → most‑advanced Pirate (or None)."""
        front = {c: None for c in range(NUM_COLUMNS)}
        for p in engine.pirates:
            cur = front[p.column]
            if cur is None or p.position > cur.position:
                front[p.column] = p
        return front

    @staticmethod
    def _pirates_by_column(engine):
        """Return dict column → list of pirates in that column (any order)."""
        cols = {c: [] for c in range(NUM_COLUMNS)}
        for p in engine.pirates:
            cols[p.column].append(p)
        return cols
