            rounds_left = MAX_POSITION - pirate.position
            cannon = engine.cannons.get(col)
            cur_damage = cannon.damage if cannon else 0
            # total damage this cannon can still deliver (including this round)
            total_possible = cur_damage * rounds_left
            deficit = max(0, pirate.hp - total_possible)
            if deficit > 0:
                deficits.append((deficit, pirate.position, col))

        # 2️⃣  If any column cannot be cleared with current damage, try to merge
        if deficits:
            # pick the column that needs the most extra damage;
            # tie‑break by furthest pirate, then lowest column
            deficits.sort(key=lambda x: (-x[0], -x[1], x[2]))
            _, _, target = deficits[0]

            donor = self._choose_weakest_donor(engine.cannons, exclude=target)
            if donor is not None:
                # merge weakest into the target column
                return ("move", donor, target)
            else:
                # no donor available – spawn a new cannon in the target column
                return ("spawn", target)

        # 3️⃣  No urgent deficits.
        # 3a – Spawn in any column that has a pirate but no cannon yet.
        for col in range(NUM_COLUMNS):
            if col not in engine.cannons and front.get(col) is not None:
                return ("spawn", col)

        # 3b – If there are empty columns, just fill the first one.
        empty_cols = [c for c in range(NUM_COLUMNS) if c not in engine.cannons]
        if empty_cols:
            return ("spawn", empty_cols[0])

        # 4️⃣  All columns occupied and no immediate threat.
        # Merge the weakest cannon into the column with the most threatening pirate.
        weakest_col = min(engine.cannons.items(),
                         key=lambda kv: (kv[1].damage, kv[0]))[0]

        # choose target: column with a front pirate having the highest position;
        # if none, fall back to the strongest cannon column.
        target = None
        best_pos = -1
        for col, pirate in front.items():
            if pirate is not None and pirate.position > best_pos:
                best_pos = pirate.position
                target = col
        if target is None:
            # no pirates left – just merge weakest into strongest cannon column
            target = max(engine.cannons.items(),
                         key=lambda kv: (kv[1].damage, -kv[0]))[0]

        if weakest_col != target:
            return ("move", weakest_col, target)

        # 5️⃣  Fallback – spawn on the weakest column (will merge with itself next round)
        return ("spawn", weakest_col)

    # --------------------------------------------------------------------- #
