```python
NUM_COLUMNS = 5
MAX_POSITION = 3  # reaching this loses the game


class Policy:
    name = "damage_deficit_merge_v2"

    def choose_action(self, engine):
        front = self._front_pirates(engine)

        # ---------- 1. Compute deficit per column ----------
        deficits = {}
        for col, pirate in front.items():
            if pirate is None:
                continue
            rounds_left = MAX_POSITION - pirate.position
            if rounds_left <= 0:
                # already at loss line – treat as infinite deficit
                deficits[col] = float('inf')
                continue
            cannon = engine.cannons.get(col)
            cur_dmg = cannon.damage if cannon else 0
            # If we spawn a cannon here this round we gain +1 damage immediately
            possible_dmg = cur_dmg * rounds_left
            deficits[col] = pirate.hp - possible_dmg

        # ---------- 2. Choose most urgent column ----------
        urgent_cols = [c for c, d in deficits.items() if d > 0]
        if urgent_cols:
            # column with largest shortfall
            target = max(urgent_cols, key=lambda c: deficits[c])
            # try to merge a donor cannon into target
            donor = self._choose_donor(engine.cannons, exclude=target)
            if donor is not None:
                return ("move", donor, target)
            # no donor → spawn a new cannon (damage 1) in target
            return ("spawn", target)

        # ---------- 3. No urgent deficit – handle normal growth ----------
        # 3a. Prefer spawning into an empty column that already has a pirate
        empty_with_pirate = [
            c for c in range(NUM_COLUMNS)
            if c not in engine.cannons and front.get(c) is not None
        ]
        if empty_with_pirate:
            col = max(empty_with_pirate,
                      key=lambda c: front[c].position)
            return ("spawn", col)

        # 3b. Strengthen columns where cannon damage is still below needed hp
        undersized = []
        for col, cannon in engine.cannons.items():
            pirate = front.get(col)
            if pirate is None:
