        if empty:
            return ("spawn", empty[0])

        # 3d. All columns occupied – merge weakest into the column with the most threatening pirate
        weakest_col = min(engine.cannons.items(),
                          key=lambda kv: (kv[1].damage, kv[0]))[0]
        # target = column whose front pirate is furthest advanced
        target = max(
            (c for c in engine.cannons if front.get(c) is not None),
            key=lambda c: front[c].position,
            default=weakest_col,
        )
        if weakest_col != target:
            return ("move", weakest_col, target)

        # 3e. Fallback – spawn on weakest column (will merge with itself next round)
        return ("spawn", weakest_col)

