```python
NUM_COLUMNS = 5
MAX_POSITION = 3  # reaching this loses the game


class Policy:
    name = "damage_deficit_merge_v2"

    def choose_action(self, engine):
        # ----- gather data per column ---------------------------------
        pirates_by_col = {c: [] for c in range(NUM_COLUMNS)}
        for p in engine.pirates:
            pirates_by_col[p.column].append(p)

        front = self._front_pirates(engine)          # most‑advanced pirate per column
        cannons = engine.cannons                     # existing cannons

        # ----- compute deficit (needed extra damage) for each column with a cannon -----
        deficits = []  # list of (deficit, col) where deficit > 0
        for col, cannon in cannons.items():
            col_pirates = pirates_by_col[col]
            if not col_pirates:
                continue  # no threat in this column

            # rounds left before the *first* pirate in this column would reach 3
            rounds_left = min(MAX_POSITION - p.position for p in col_pirates)
            if rounds_left <= 0:
                # already lost – but we still return a move to keep deterministic
                continue

            total_hp = sum(p.hp for p in col_pirates)
            potential_damage = rounds_left * cannon.damage
            deficit = total_hp - potential_damage
            if deficit > 0:
                deficits.append((deficit, col))

        # ----- 1️⃣  If any column is in danger, try to fix it now -----
        if deficits:
            # pick the column with the largest deficit (most urgent)
            _, target_col = max(deficits, key=lambda kv: (kv[0], -kv[1]))

            # look for a donor cannon (the weakest one that is not the target)
            donor = self._choose_weakest_donor(cannons, exclude=target_col)
            if donor is not None:
                return ("move", donor, target_col)
            # no donor → spawn a new cannon that will merge next round
            return ("spawn", target_col)

        # ----- 2️⃣  No immediate danger: ensure we have cannons where pirates exist -----
        # columns that have pirates but no cannon yet
        empty_with_pirate = [
            c for c in range(NUM_COLUMNS)
            if c not in cannons and pirates_by_col[c]
        ]
        if empty_with_pirate:
            # choose the column whose front pirate is closest to the loss row
            target = max(empty_with_pirate,
                         key=lambda c: front[c].position if front[c] else -1)
            return ("spawn", target)

        # ----- 3️⃣  All columns with pirates already have cannons and are safe.
        # If there are still empty columns, just place a cannon there.
        empty_cols = [c for c in range(NUM_COLUMNS) if c not in cannons]
        if empty_cols:
            return ("spawn", empty_cols[0])

        # ----- 4️⃣  All columns occupied and safe: keep building damage.
        # Merge the weakest cannon into the column that will benefit most from extra damage.
        # Benefit is measured by (total_hp - rounds_left * damage) i.e. current deficit (could be zero).
        # We recompute deficits allowing zero values to pick the best target.
        benefit_list = []
        for col, cannon in cannons.items():
            col_pirates = pirates_by_col[col]
            if not col_pirates:
                continue
            rounds_left = min(MAX_POSITION - p.position for p in col_pirates)
            total_hp = sum(p.hp for p in col_pirates)
            current_damage = rounds_left * cannon.damage
            benefit = total_hp - current_damage  # larger = more need for extra damage
            benefit_list.append((benefit, col))

        if benefit_list:
            # pick column with highest benefit (most need), tie‑break by lower column index
            _, target_col = max(benefit_list, key=lambda kv: (kv[0], -kv[1]))
            donor = self._choose_weakest_donor(cannons, exclude=target_col)
            if donor is not None and donor != target_col:
                return ("move", donor, target_col)

        # ----- 5️⃣  Fallback: nothing else to do – spawn on the weakest column -----
        weakest = min(cannons.items(), key=lambda kv: (kv[1].damage, kv[0]))[0]
        return ("spawn", weakest)

    # --------------------------------------------------------------------- #
    @staticmethod
    def _front_pirates(engine):
        """Return dict column → most‑advanced Pirate (or None)."""
        front = {c: None for c in range(NUM_COLUMNS)}
        for p in engine.pirates:
            cur = front[p.column]
            if cur is None or p.position > cur.position:
                front[p.column] = p
        return front

    @staticmethod
