        """Return column of the weakest cannon not equal to *exclude*, or None."""
        candidates = [
            (col, c.damage) for col, c in cannons.items() if col != exclude
        ]
        if not candidates:
            return None
        # deterministic: weakest damage, then lowest column index
        donor = min(candidates, key=lambda kv: (kv[1], kv[0]))[0]
        return donor
